def cl(x):
 if isinstance(x,np.integer): return int(x)
 if isinstance(x,np.floating): return None if not np.isfinite(x) else float(x)
 if isinstance(x,(pd.Timestamp,datetime.datetime,datetime.date)): return x.isoformat()
 if isinstance(x,dict): return {str(k):cl(v) for k,v in x.items()}
 if isinstance(x,(list,tuple)): return [cl(v) for v in x]
 return x
def summ(s):
 q=s.quantile([.25,.5,.75]); return {'n':int(s.count()),'mean':float(s.mean()),'median':float(s.median()),'std':float(s.std()),'min':float(s.min()),'q1':float(q.iloc[0]),'q3':float(q.iloc[2]),'max':float(s.max()),'sum':float(s.sum())}
