 a=[]
 for k,g in df.groupby(c): a.append({c:int(k),'n':len(g),'cnt_mean':float(g.cnt.mean()),'cnt_median':float(g.cnt.median()),'cnt_sum':int(g.cnt.sum()),'casual_mean':float(g.casual.mean()),'registered_mean':float(g.registered.mean())})
 return a
